// Protected aggregate composition, atomic Store rollback, and owned new receipts.
fn unified_group_compound_new_write(originals:&[OperationRecord])->PreparedOperation {
    let mut group=grouped_prepared(&originals[0],true);
    let mut compound=compound_scope(&[originals[1].clone()]);
    let EffectConstraint::CompoundSubmissionMutations{children}=&mut compound.intent.expected[0]else{unreachable!()};children[0].incremental_valuation=compound.valuation.clone();
    let mut new=originals[0].preview.clone().unwrap();new.intent.expected=vec![EffectConstraint::Conversion{resource:resource("binance-account"),input:asset("binance","ETH",18),maximum_input:quantity("1000000000000000000"),output:asset("binance","USDC",6),minimum_output:quantity("1000000")}];let scope=gofin_domain::amendments::AmendmentScope{intent:new.intent.clone(),binding:new.binding.clone(),valuation:new.valuation.clone()};
    let mut inputs=group.input["amendments"].as_array().unwrap().clone();inputs.extend(compound.input["amendments"].as_array().unwrap().iter().cloned());group.input["amendments"]=json!(inputs);
    group.intent.debits.extend(compound.intent.debits);group.intent.debits.extend(new.intent.debits.clone());group.intent.maximum_costs.extend(compound.intent.maximum_costs);group.intent.maximum_costs.extend(new.intent.maximum_costs.clone());group.intent.expected.extend(compound.intent.expected);group.intent.expected.extend(new.intent.expected.clone());
    group.intent.locks.extend(compound.intent.locks);group.intent.locks.extend(new.intent.locks.clone());group.intent.locks.sort();group.intent.locks.dedup();group.valuation.as_mut().unwrap().movement_usd_micros=quantity("4000000");group.binding["mutationNewWriteScope"]=to_value(&scope).unwrap();group
}
fn unified_receipt(record:&OperationRecord,group_children:Vec<gofin_domain::compound_mutations::MutationChildProof>,independent:gofin_domain::compound_mutations::MutationChildProof)->VerifiedEffects{
    let mut v=grouped_receipt(record,group_children);let c=compound_receipt(record,vec![independent]);v.effects.extend(c.effects);v.effects.push(FinancialEffect::Conversion{resource:resource("binance-account"),spent:Amount{asset:asset("binance","ETH",18),atoms:quantity("1000000000000000000")},received:Amount{asset:asset("binance","USDC",6),atoms:quantity("1000000")}});let mut events=v.evidence["proofEvents"].as_array().unwrap().clone();events.extend(c.evidence["proofEvents"].as_array().unwrap().iter().cloned());events.push(json!({"eventId":"synthetic-new-financial-receipt","amount":"1000000000000000000"}));v.evidence["proofEvents"]=json!(events);v.proof_digest=verified_effect_digest(&v).unwrap();v
}
#[tokio::test]
async fn unified_group_compound_new_receipt_commits_atomically_and_recovers_after_restart(){
    use gofin_domain::compound_mutations::{MutationChildProof,ChildMutationOutcome};
    let d=tempfile::tempdir().unwrap();let path=d.path().join("unified-mutations.sqlite");let e=synthetic_engine(&path,Arc::new(GroupedFixture(SyntheticAdapter::new())));let originals=compound_originals(&e).await;let prepared=unified_group_compound_new_write(&originals);e.validate_submission_amendment(&prepared,None,false).unwrap();
    let mut mutation=originals[0].clone();mutation.id="synthetic-unified-mutation".into();mutation.request_id=mutation.id.clone();mutation.fingerprint=mutation.id.clone();mutation.input=prepared.input.clone();mutation.preview=Some(prepared.clone());mutation.status=Status::AwaitingApproval;mutation.submission=None;mutation.effects=None;mutation.last_reconciliation_evidence=None;mutation.approval.as_mut().unwrap().binding_hash=binding_hash(&authorization_binding(&prepared)).unwrap();e.store.lock().unwrap().create_request(&mutation.id,&mutation.request_id,&mutation.fingerprint,&mutation.operation,None,"awaiting_approval",&to_value(&mutation).unwrap(),&now()).unwrap();e.reserve_ordinary_operation(&mut mutation,&prepared, None, None).unwrap();let dispatch=Submission{kind:"synthetic_tx".into(),reference:"synthetic-unified-dispatch".into(),data:json!({"synthetic":true})};e.store.lock().unwrap().persist_submission(&mutation.id,&SubmissionRow{kind:dispatch.kind.clone(),reference:dispatch.reference.clone(),data:dispatch.data.clone()},&now()).unwrap();mutation=e.load_record(&mutation.id).unwrap();
    let EffectConstraint::GroupedSubmissionAmendments{group}=&prepared.intent.expected[0]else{unreachable!()};let first=MutationChildProof{child_tag:"member-0".into(),operation_id:originals[0].id.clone(),submission:originals[0].submission.clone().unwrap(),outcome:ChildMutationOutcome::Accepted{successor:None},native_evidence:json!({"bindingReplacementDigest":binding_hash(&to_value(&group.children[0].binding_replacements).unwrap()).unwrap(),"nativeAudit":{"id":"synthetic-group-audit"},"nativeReadback":{"size":"2"}})};let independent=MutationChildProof{child_tag:"child-0".into(),operation_id:originals[1].id.clone(),submission:originals[1].submission.clone().unwrap(),outcome:ChildMutationOutcome::Accepted{successor:None},native_evidence:json!({"nativeAudit":"synthetic-independent-amendment"})};let v=unified_receipt(&mutation,vec![first.clone()],independent.clone());
    // Force a late independent-owner CAS/proof error AFTER the grouped helper
    // would have changed its original reservation. Every table must roll back.
    let mut next=mutation.clone();next.status=Status::Pending;next.effects=Some(v.clone());next.updated_at=now();let groups=e.grouped_settlements(&next).unwrap();let mut children=e.compound_child_settlements(&next).unwrap().unwrap();children[0].proof["native_evidence"]=json!({"conflict":"synthetic wrong immutable child"});let remaining=e.remaining_mutation_reservations(&next,&groups).unwrap();assert!(e.store.lock().unwrap().commit_mutation_batch_progress(&next.id,&to_value(&mutation).unwrap(),&to_value(&next).unwrap(),&to_value(&v).unwrap(),&to_value(&v.effects).unwrap(),&groups,&children,&remaining,&next.updated_at).is_err());for o in &originals{assert!(e.amendment_context(&o.id).unwrap().revisions.is_empty());assert_eq!(e.load_record(&o.id).unwrap(),*o);}
    let partial=e.apply_reconciliation(mutation,Reconciliation{status:Status::Pending,evidence:v.evidence.clone(),verified:Some(v)}).unwrap();assert!(e.has_pending_amendment(&originals[0].id).unwrap());assert!(!e.has_pending_amendment(&originals[1].id).unwrap(),"a proved owner can recover while another sibling/new financial record stays pending");for o in &originals{assert_eq!(e.amendment_context(&o.id).unwrap().revisions.len(),1);assert_eq!(e.load_record(&o.id).unwrap(),*o);}
    drop(e);let e=synthetic_engine(&path,Arc::new(GroupedFixture(SyntheticAdapter::new())));let restored=e.load_record(&partial.id).unwrap();assert_eq!(restored.effects,partial.effects);let second=MutationChildProof{child_tag:"member-1".into(),operation_id:originals[0].id.clone(),submission:originals[0].submission.clone().unwrap(),outcome:ChildMutationOutcome::Rejected{code:"INSUFFICIENT_FUNDS".into()},native_evidence:json!({"error":"synthetic second member rejected"})};let v=unified_receipt(&restored,vec![first,second],independent);let final_record=e.apply_reconciliation(restored,Reconciliation{status:Status::Failed,evidence:v.evidence.clone(),verified:Some(v)}).unwrap();assert_eq!(final_record.status,Status::Failed);assert_eq!(e.store.lock().unwrap().reservation_count(&final_record.id).unwrap(),0);assert!(final_record.effects.as_ref().unwrap().effects.iter().any(|effect|matches!(effect,FinancialEffect::Conversion{..})),"truthful owned new financial receipt remains despite rejected authority sibling");for o in &originals{assert_eq!(e.load_record(&o.id).unwrap(),*o);assert!(!e.has_pending_amendment(&o.id).unwrap());}assert_eq!(e.allocation_used_usd_micros().unwrap(),"6000000");
}
